from pathlib import Path
import json
R=Path(__file__).resolve().parent
p=json.loads((R/'front-master-rebuild-v1.procedure.json').read_text());URL=p['source']['source_url']
p.update(id='yamaha-2026-yz450f-us-clutch-hydraulic-service-v1',title='Service the clutch hydraulics',component='clutch',affected_components=['clutch','clutch_master','clutch_release','clutch_hose','handlebar'],completeness='Complete hydraulic-circuit service using a new master-cylinder kit and a complete replacement release cylinder, with both hose ends disconnected, cleaned and refilled. Does not rebuild release-cylinder internals or service clutch plates.',entry_state=['Assembled exact US2026 stock YZ450F; engine stopped and cool.','Serviceable mechanical clutch, pushrod and engine-side oil seal; exact master kit and complete replacement release cylinder available.'],exit_state=['Master kit renewed; replacement release cylinder fitted with new mounting seal; circuit cleaned and connected.','Clutch fluid at its baseline, circuit bled and closed, lever/routing/operation checked.'])
p['applicability']=dict(included='Stock hydraulic clutch on exact US2026 YZ450F',excluded=['Other years and aftermarket hydraulic systems','Release-cylinder internal piston/seal overhaul','Mechanical clutch plates or pushrod/oil-seal repair'],year_inheritance='NONE')
p['required_tools']=[dict(name='Stable stand, clean containers, hand and retaining-ring tools',size='Match stock hardware'),dict(name='Precision torque tools',size='1.5–30 Nm'),dict(name='Clear bleed hose and waste container',size='Match clutch release bleeder'),dict(name='Compressed air and eye protection',size='Clear blocked master passages')]
p['required_parts']=[dict(name='Exact new clutch master-cylinder kit',purpose='Diagram253 kit including new piston seals'),dict(name='Complete exact stock replacement release cylinder',purpose='Assembly replacement; no internal rebuild instructions asserted'),dict(name='New release-cylinder mounting O-ring',purpose='Engine interface'),dict(name='Four new copper hose union washers',purpose='Two at each disconnected hose end'),dict(name='Fresh DOT4 clutch fluid',purpose='Clean, lubricate and refill entire hydraulic circuit'),dict(name='Silicone grease',purpose='Source-marked master pushrod/lever and release mounting seal/contact'),dict(name='LOCTITE locking agent',purpose='Release mounting bolts; OEM does not specify product grade')]
rows=[
('prepare','Prepare hydraulic service','Stop/cool engine and support bike on level ground. Clean release-cylinder area and protect surfaces. Check fluid at horizontal master: above baseline requires friction-plate wear inspection, below baseline requires leak inspection before treating this as hydraulic-only work.',[100,196,254],'Mechanical clutch serviceable; fluid history and visible defects recorded.',True),
('drain','Drain entire circuit','Remove master cap and diaphragm. Put hose/container on release bleeder and drain fluid with clutch lever/bleeder cycle. Disconnect both hose unions and discard all four copper washers, catching residual fluid.',[100,101,252,261,262],'Entire circuit drained; no old fluid reused.',False),
('access','Remove release cylinder','Remove drive-sprocket cover and its two bolts. Unbolt and withdraw release cylinder while retaining interface washer. Leave engine pushrod and its oil seal installed; prevent lever operation with unit off.',[196,254,257],'Engine-side rod/seal untouched; mounting area protected from dirt.',False),
('master-off','Remove master','Remove lever pivot bolt/nut, lever and bushing. Remove master holder and master, retaining paint-mark position and left-switch lead routing.',[252,261,164],'Hardware identified; adjacent controls/lead undamaged.',False),
('master-strip','Remove old master kit','Remove boot/pushrod, retaining ring and piston/spring/seals in diagram253 order, controlling spring release. Inspect body for cracks/damage and bore/kit for rust, scratches or wear; damaged master and kit must be replaced together.',[253,261],'Record master condition; no damaged bore reused.',True),
('clean','Clean hydraulic parts','Clean disconnected hose and master internals with fresh DOT4, never solvents. Clear blocked master fluid passages with compressed air. Inspect hose, reservoir and diaphragm; replace damaged parts. Discard drained cleaning fluid.',[261,262],'Clean passages; serviceable hose/reservoir/diaphragm.',False),
('master-kit','Install new master kit','Lubricate internal kit parts with fresh DOT4. Fit new seals in diagram253 positions/orientations, then spring/piston, retaining ring, pushrod and boot in the illustrated order. Apply silicone grease at the marked pushrod surfaces and verify ring seating.',[7,253,261],'Record new seals and diagram-matched orientation/retention.',True),
('master-fit','Refit master and lever','Fit holder UP upward with its end at handlebar paint mark; restore switch lead through holder. Tighten upper holder bolt first, then lower, both9 Nm. Restore bushing and lever, lubricating marked locations with silicone grease; pivot bolt6 Nm and nut6 Nm.',[164,252,261,262],'Record holder alignment/sequence and lever torques.',True),
('release-fit','Install replacement release cylinder','Fit new mounting O-ring with silicone grease; retain washer in diagram257 position. Grease exposed pushrod-end contact. Seat replacement cylinder without trapping seal. Apply specified LOCTITE treatment to mounting bolts and tighten10 Nm.',[7,254,257],'Record new O-ring, washer position and10 Nm mounting torque.',True),
('unions','Connect both hose ends','Use two new copper washers per union. At master, white paint dot faces forward and aligns with body projection. At release, pipe touches its body stop as263. Tighten both union bolts30 Nm; steer both ways to verify hose clearance.',[262,263],'Record four washers, both stop orientations and30 Nm unions.',True),
('fill','Fill to clutch baseline','With reservoir top horizontal, fill fresh DOT4 to the exact baseline shown on100. Fit diaphragm; avoid overflow or water entry. Connect clear hose securely to release bleeder with outlet in catch container.',[100,101,262,263],'Fluid at clutch baseline; do not substitute brake minimum-mark rule.',False),
('bleed','Bleed the clutch','Slowly squeeze lever several times, then fully squeeze and hold. Open bleeder; close before releasing lever. Repeat until bubbles disappear, keeping sufficient fluid in reservoir. If tiny bubbles persist, let fluid settle a few hours and repeat.',[100,101],'Record bubble-free fluid and firm lever response.',True),
('close','Close hydraulic circuit','Tighten release bleeder5 Nm, refit its cap and restore clutch fluid baseline. Refit diaphragm and cap without overflow; cap screws1.5 Nm. Clean spills. Refit sprocket cover with both bolts7 Nm.',[100,101,252,254],'Record fluid baseline and closure torques.',True),
('lever','Set lever position','Push clutch lever forward while turning its adjusting bolt to desired reach, then tighten locknut5 Nm. Check free lever movement and hose clearance at both steering limits.',[99,100,262],'Record lever adjustment and routing check.',False),
('verify','Check clutch function','Inspect all hydraulic connections and mounts for leakage/security. Verify normal clutch operation; soft or spongy lever requires further bleeding. Persistent slipping, drag or abnormal operation requires mechanical-clutch diagnosis.',[90,100,101,262,263],'Record no leaks and normal clutch operation; unresolved faults prevent completion.',True),
]
p['steps']=[];prev=[]
for sid,title,txt,pages,verify,record in rows:
 p['steps'].append(dict(id=sid,title=title,instruction=txt,source_pdf_pages=pages,source_links=[URL+'#page='+str(n) for n in pages],depends_on=prev.copy(),verification=verify,record_required=record,diagram_reference_required=True,origin='Yamaha OEM service manual; original factual companion'));prev=[sid]
p['source']['pdf_pages']=sorted({n for s in p['steps'] for n in s['source_pdf_pages']});p['source']['review_note']='Visual252/253/101 and prior approved release access254/257. Entire circuit disconnected/cleaned as261, complete release replacement because262–263 contains no internal rebuild. DOT4 level is clutch baseline100, not brake minimum. Kit orientation requires original253 diagram.'
p['preflight']=['Keep exact kit/union/level diagrams available.','Yamaha recommends renewing friction and clutch plates when changing clutch fluid; plate service is a separate operation.','Protect surfaces/eyes; do not operate clutch with release unit unbolted.'];p['critical_stop_conditions']=['Mechanical clutch wear/fault outside hydraulic scope.','Damaged master/hose, uncertain kit orientation or unseated retention.','Persistent leak, soft lever or abnormal clutch operation.']
(R/'clutch-hydraulic-service-v1.procedure.json').write_text(json.dumps(p,indent=2)+'\n')
